window.RP_SESSION={"id":"S-b8957d687549","messages":[{"id":"RP-II-0126641","time":"2026-07-28T15:49:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"위대한 지도자 납시오~~!!!\"\n한 티플링 소녀가 숲길에서 주운 기다란 나뭇가지를 지팡이로 짚고 소리칩니다\n\n자기들끼리 기사, 마법사, 왕 등 역할을 정하고 놀고 있던 다른 아이들은, 갑자기 난입한 티플링 소녀를 일제히 바라봅니다.\n\n...\n\n마침 괴물 역할이 필요했는데, 잘됬잖아?","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126642","time":"2026-07-28T15:51:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"이야!! 저기 괴물을 죽여라!!\"","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126643","time":"2026-07-28T15:52:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"나뭇잎을 엮어 만든 조잡힌 왕관을 쓰고 있던 아이가, 티플링 소녀를 향해 소리칩니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126644","time":"2026-07-28T15:53:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"그러자 다른 두 명의 남자아이들이 일제히 소녀를 향해 달려듭니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126645","time":"2026-07-28T15:55:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"\"으악?!!\"\n\n그중 하나가 소녀를 넘어뜨린 후 나뭇가지로 마구 때리고,\n나머지 한명은 주문 영창을 흉내내며 소리를 빽빽 지릅니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126646","time":"2026-07-28T15:56:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":".\n.\n.\n그날 이후 그 소녀는 아이들 사이에서 괴물이라고 불리게 되어,\n\n아이들과 마주칠 때마다 괴물 소릴 들으며 쫓겨야 했습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126647","time":"2026-07-28T15:58:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"하지만 티플링 소녀 말고도, 아이들 무리에 끼지 못한 아이가, 한 명 더 있었습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126648","time":"2026-07-28T15:59:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"아사그 마을에서 가장 눈에 띄는 건물.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126649","time":"2026-07-28T16:00:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"이름도 특이한 조(Zoe) 가문의 성,\n그곳엔 아이들이 단 한번도 밖에 나오는 걸 본 적이 없는,","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126650","time":"2026-07-28T16:01:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"아마이라는 특이한 이름을 가진 소년이 살고 있었거든요.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126651","time":"2026-07-28T16:04:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"아이들 중 한 명은 야심한 밤에,\n그날따라 잠이 잘 안 들던 날,\n목적없이 창문을 바라보며 멍을 때리다..\n성에서 그 아이가 밖으로 나오는 걸 봤다고 얘기하기도 했습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126652","time":"2026-07-28T16:06:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"하지만 왜인지 그 아인 태양이 떠있을 땐 한번도 모습을 비추지 않았고,\n\n정체불명의 괴물이라는 얘기만 아이들 사이에서 떠돌 뿐이었습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126653","time":"2026-07-28T16:07:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"티플링 소녀는.. 아니,","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126654","time":"2026-07-28T16:08:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"마젤란토는.\n아이들의 얘길 엿듣고 그 아이가 궁금해져서,\n밤에 저 성 근처에 숨어있어보기로 합니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126655","time":"2026-07-28T16:09:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126656","time":"2026-07-28T16:09:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]},{"id":"RP-II-0126974","time":"2026-07-28T22:50:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]},{"id":"RP-II-0126975","time":"2026-07-29T01:42:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":".","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126976","time":"2026-07-29T01:44:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"!예언","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126977","time":"2026-07-29T01:44:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...끔찍한 말들이 오갈 것이다.","characters":[]},{"id":"RP-II-0126978","time":"2026-07-29T01:45:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"딱 어울리네","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126979","time":"2026-07-29T01:46:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"”괴물이다!! 피부색도 이상하고, 괴상한 뿔도 달려있어!!!“","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126980","time":"2026-07-29T01:47:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"”얼른 저 녀석의 목을 따와라!!“\n”이야아아앗~~!!“","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126981","time":"2026-07-29T01:47:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"해봤자 겨우 열 살을 넘겼을 아이들 치곤 꽤나 나쁜 말들이 마을에 울려퍼집니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126982","time":"2026-07-29T01:49:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"그리고, 아는 세상이라곤 성 안과 다양한 책들, 하얀 종이가 전부인 소년은 이젠 익숙하단 듯, 그 소릴 신경쓰지 않고 있었습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126983","time":"2026-07-29T01:50:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"그날 밤 전까지는요.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126984","time":"2026-07-29T01:51:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"소년은 요즘들어 밤에 몰래 산책을 나가는 것에 맛들렸습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126985","time":"2026-07-29T01:52:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"최근 지하통로를 발견해서, 하인들 몰래 그리로 들락날락..","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126986","time":"2026-07-29T01:53:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"그날 밤도 역시나 조심조심, 아무도 모르게 밖으로 나오던 참이었습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126987","time":"2026-07-29T01:53:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"!민첩-2","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126988","time":"2026-07-29T01:54:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'아마이 조'의 민첩 판정 :\n[7] + [2] + [-2] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0126989","time":"2026-07-29T01:54:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"하지만, 누군가에게 들킨 것 같군요.\n그나마 다행인건 하인이나 부모님께 들킨 게 아니란 거?","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126990","time":"2026-07-29T01:55:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"숲길을 향해 가던 소년의 어깨를 누군가 톡톡, 건드립니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126991","time":"2026-07-29T01:56:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"“우아아아아악!?.??”","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126992","time":"2026-07-29T01:56:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"소년의 뒤에는, 또래처럼 보이는 티플링 소녀가 있었습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126993","time":"2026-07-29T01:56:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"아이들에게 허구한 날 괴물이라 불리며 쫓겨다니는 그 소녀네요.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126994","time":"2026-07-29T01:59:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"”…안녕? 이름이 뭐야?“\n소녀가 해맑게 웃으며 말을 건넵니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126995","time":"2026-07-29T02:00:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"소년은 한껏 움츠러든 채로 가만히 소녀를 쳐다봅니다","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126996","time":"2026-07-29T02:00:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"또래랑 마지막으로 대화해본게 언제였지..?","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126997","time":"2026-07-29T02:02:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"19초간 정적이..","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126998","time":"2026-07-29T02:02:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"…19초나?","characters":["P-5d58655d55ce"]},{"id":"RP-II-0126999","time":"2026-07-29T02:04:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"19초 중 5초는 머리가 새하얘진 상태였을 것이고,\n3초는 소녀를 인식하는데에,\n11초는 어떡하지? 일단 입을 열고…. 목소리를 어떻게 내더라?\n이런 생각을 하는데에 썼을 겁니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127001","time":"2026-07-29T02:06:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"소년이 겨우 혀를 입천장에 댄 순간,\n기다리다 못한 소녀가 말을 채갑니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127002","time":"2026-07-29T02:06:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"“난 마젤란토라고 해! 너는?”","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127003","time":"2026-07-29T02:07:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"“……….”\n3초동안 또 조용히 있다가, 드디어 소년이 목소리를 냅니다.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127004","time":"2026-07-29T02:08:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"“(아)마(이) 조.”\n아이고, 목소리가 제대로 안 나와요.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127005","time":"2026-07-29T02:09:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"”마조?“\n”아니아니아니! 아마이 조!!“","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127006","time":"2026-07-29T02:10:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"소리를 좀 크게 내니, 이제서야 목이 풀렸네요.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127007","time":"2026-07-29T02:11:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"…\n원래 친구 없는 애들끼리 뭉치는 법이죠.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127008","time":"2026-07-29T02:12:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"첫만남이 살짝 엉망이지만,","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127009","time":"2026-07-29T02:12:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"그래도 두 아이는 잘 지내게 될 것 같지 않나요? 헹헹!","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127010","time":"2026-07-29T02:12:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"…아님말고.","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127011","time":"2026-07-29T02:12:00+09:00","room":"RP II","name":"어린 아마이 조 / 마젤란토 / 서술","profile":"베어","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5d58655d55ce"]},{"id":"RP-II-0127012","time":"2026-07-29T02:12:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
